import {chromium} from '@playwright/test';
import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import {KEY,scenarioState} from '../src/model.js';
const base='http://127.0.0.1:5184',dir='检查记录/子功能凝练_20261021',b=await chromium.launch({executablePath:'C:/Program Files/Google/Chrome/Application/chrome.exe',headless:true,args:['--no-proxy-server']}),p=await b.newPage({viewport:{width:1440,height:1000}}),results=[],errors=[];
p.setDefaultTimeout(7000);p.on('pageerror',e=>errors.push(e.message));
async function load(route,s='PT01',lang='zh'){await p.goto(base);await p.evaluate(({k,s,lang})=>{localStorage.setItem(k,JSON.stringify(s));localStorage.setItem('career-prototype-language',lang);localStorage.setItem('career-prototype-operation-guide-v1',JSON.stringify({enabled:false,neverPrompt:true,active:null,seen:[]}));},{k:KEY,s:typeof s==='string'?scenarioState(s):s,lang});await p.goto(base+route);await p.locator('.page-surface').waitFor();await p.emulateMedia({reducedMotion:'reduce'});await p.addStyleTag({content:'*,*::before,*::after{animation:none!important;transition:none!important}'});}
const state=()=>p.evaluate(k=>JSON.parse(localStorage.getItem(k)),KEY);
async function check(name,fn){try{await fn();results.push({name,status:'pass'});console.log('PASS',name);}catch(e){results.push({name,status:'fail',error:e.message});console.log('FAIL',name,e.message.slice(0,700));await p.screenshot({path:dir+'/失败-'+results.length+'.png'});}}
async function shot(name,selector){const toast=p.locator('.toast.show button');if(await toast.count())await toast.click();await p.locator('#main').evaluate(e=>e.scrollTop=0);await p.waitForTimeout(200);await p.screenshot({path:dir+'/'+name+'-视口.png'});if(selector){const v=p.viewportSize(),el=p.locator(selector),box=await el.boundingBox();await p.setViewportSize({width:v.width,height:Math.ceil(box.height+650)});await p.locator('#main').evaluate(e=>e.scrollTop=0);await el.screenshot({path:dir+'/'+name+'-板块.png'});await p.setViewportSize(v);}}
try{
 await check('薪酬归入岗位详情，旧链接可达且不泄露私人岗位',async()=>{const s=scenarioState('PT05');s.jobs.push({id:'private-test',title:'PRIVATE_TITLE',text:'PRIVATE_TEXT'});await load('/careers?tab=薪酬参考&job=original',s);assert.equal(new URL(p.url()).searchParams.get('tab'),'企业与岗位');assert.equal(new URL(p.url()).searchParams.get('job'),'original');assert.equal(await p.locator('.tabs>a').count(),4);assert.equal(await p.locator('.salary-context').evaluate(e=>e.open),true);assert.match(await p.locator('.salary-context').innerText(),/尚无获准/);assert.doesNotMatch(await p.locator('.job-discovery').innerText(),/PRIVATE_/);await shot('1440-岗位与薪酬','.salary-context');});
 await check('空评估提供四类实际核对路径，不擅自创建分析或行动',async()=>{await load('/assessment?tab=职业评估');const r=p.getByRole('region',{name:'职业准备核对'});assert.equal(await r.locator('dl>div').count(),4);assert.match(await r.innerText(),/尚无相关确认材料/);const before=await state();await r.getByRole('button',{name:'安排一次有限验证',exact:true}).click();await p.locator('dialog[open]').waitFor();assert.equal((await state()).tasks.length,0);assert.equal((await state()).analysis,null);await p.keyboard.press('Escape');assert.deepEqual((await state()).claims,before.claims);await shot('1440-职业评估','.preparation-review');});
 await check('有材料评估保留创建快照与既有四维依据',async()=>{await load('/assessment?tab=四维与差距','PT05');assert.match(await p.locator('.preparation-review').innerText(),/1 项相关确认材料/);await p.getByRole('button',{name:'创建模拟差距快照',exact:true}).click();await p.locator('.evidence-assessment').waitFor();assert.equal(await p.locator('.preparation-review').count(),0);assert.equal((await state()).analysis.claims.length,2);});
 await check('空简历直达导入与资料准备，已有档案恢复筛选且不丢数据',async()=>{await load('/assessment?tab=当前简历');assert.equal(await p.locator('.resume-library-toolbar').count(),0);assert.equal(await p.locator('.resume-library-note').count(),0);assert.equal(await p.locator('.resume-start dl>div').count(),4);await shot('1440-简历起点','.resume-start');await p.getByRole('button',{name:'上传 PDF / 粘贴简历',exact:true}).click();await p.locator('.resume-import-panel').waitFor();await p.getByLabel('核对提取原文 / 粘贴简历文字').fill('项目经历\n本人记录测试过程。');await p.getByRole('button',{name:'按原文整理候选段落',exact:true}).click();await p.getByLabel('简历原稿名称').fill('合成原稿');await p.getByRole('button',{name:'仅保存原稿',exact:true}).click();assert.equal((await state()).resumeImports.length,1);assert.equal(await p.locator('.resume-library-toolbar').count(),1);assert.equal(await p.getByRole('button',{name:'查看提取内容',exact:true}).count(),1);});
 await check('计划页签收为三项，旧方案地址直达内联调整与真实影响',async()=>{await load('/plan?tab=方案调整','PT05');assert.equal(await p.locator('.tabs>a').count(),3);assert.equal(new URL(p.url()).searchParams.get('adjust'),'1');assert.equal(await p.locator('.plan-adjustment').evaluate(e=>e.open),true);assert.equal(await p.getByRole('button',{name:'模拟基线版本变化',exact:true}).count(),0);const before=await state();await p.getByRole('button',{name:'建立预算 / 范围方案',exact:true}).click();const modal=p.locator('dialog[open]');await modal.getByLabel('假设每周总预算（小时）').fill('1');await p.getByRole('region',{name:'计划变更影响'}).waitFor();assert.match(await modal.locator('tbody').innerText(),/延期/);await modal.getByRole('button',{name:'保存临时方案',exact:true}).click();assert.deepEqual((await state()).tasks,before.tasks);assert.equal((await state()).scenario.budget,'1');await shot('1440-内联方案','.plan-adjustment');await p.getByRole('button',{name:'继续预览与应用',exact:true}).click();await p.locator('dialog[open]').getByRole('button',{name:'本人确认并应用',exact:true}).click();assert.equal((await state()).budget,1);assert.equal((await state()).tasks[0].status,'延期');assert.deepEqual((await state()).claims,before.claims);});
 await check('过期副本不能覆盖计划，没有任务时不铺空阶段或假筛选',async()=>{const s=scenarioState('PT05');s.scenario={base:0,budget:1,goal:'data',policy:'延后超额任务'};await load('/plan?tab=方案调整',s);await p.getByRole('button',{name:'继续预览与应用',exact:true}).click();await p.locator('dialog[open]').getByRole('button',{name:'本人确认并应用',exact:true}).click();assert.match(await p.locator('dialog[open]').innerText(),/基线已过期/);assert.equal((await state()).budget,3);await load('/plan');assert.equal(await p.locator('.phase-columns').count(),0);assert.equal(await p.locator('.phase-start').count(),1);await load('/plan?tab=执行');assert.equal(await p.locator('.task-list-filters').count(),0);assert.match(await p.locator('.task-execution-list').innerText(),/还没有开始执行/);});
 await check('设置四页合为两组，授权与导出删除仍可达且取消不损数据',async()=>{await load('/settings?tab=资料授权','PT05');assert.equal(await p.locator('.tabs>a').count(),2);assert.equal(new URL(p.url()).searchParams.get('tab'),'资料与隐私');assert.equal(await p.getByRole('button',{name:'修改资料范围',exact:true}).count(),1);assert.equal(await p.getByRole('button',{name:'导出本地示例 JSON',exact:true}).count(),1);const before=await state();await p.getByRole('button',{name:'查看影响并删除',exact:true}).click();await p.keyboard.press('Escape');assert.deepEqual((await state()).claims,before.claims);await load('/settings?tab=反馈状态','PT05');assert.equal(await p.locator('.settings-feedback').evaluate(e=>e.open),true);assert.equal(new URL(p.url()).searchParams.get('section'),'feedback');await p.getByRole('button',{name:'提交具体版本反馈',exact:true}).click();await p.locator('dialog[open]').waitFor();await p.keyboard.press('Escape');await shot('1440-设置支持','.settings-feedback');});
 await check('桌面手机、空与有资料的结构和英文入口',async()=>{const views=[['评估','/assessment?tab=四维与差距','.preparation-review'],['简历','/assessment?tab=当前简历','.resume-start'],['方案','/plan?tab=方案调整','.plan-adjustment'],['隐私','/settings?tab=资料授权','#settings-authorization'],['薪酬','/careers?tab=薪酬参考','.salary-context']];for(const width of [390,320]){await p.setViewportSize({width,height:844});for(const [label,route,selector]of views){await load(route);assert.ok(await p.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1),label+'-'+width);if(width===390)await shot(width+'-'+label,selector);}}await load('/assessment?tab=当前简历','PT01','en');assert.match(await p.locator('.resume-start').innerText(),/Start from an existing resume/);assert.ok(await p.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1));await shot('320-EN简历','.resume-start');await p.setViewportSize({width:1440,height:1000});});
 results.push({name:'运行时错误',status:errors.length?'fail':'pass',errors});
}finally{await fs.writeFile(dir+'/验证结果.json',JSON.stringify(results,null,2));await b.close();}
if(results.some(r=>r.status==='fail'))process.exitCode=1;
